DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'crm_leads') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.crm_leads; END IF; IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'crm_follow_ups') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.crm_follow_ups; END IF; END $$;